        String rate = null;
        LocalDate latest = null;
        for (String entry : cardTaxRates.split("\u001e")) {
            String[] parts = entry.split("\u001f", -1);
            if (parts.length != 3 || !parts[0].equalsIgnoreCase(unitType.trim())) {
